function core(){return corePromise||(corePromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='bpo-core.factors-7af4e00573cb.js';s.onload=async()=>{try{await window.PropertyThesisBPOCore.prepareValidation();resolve(window.PropertyThesisBPOCore);}catch(e){corePromise=null;reject(e);}};s.onerror=()=>{corePromise=null;reject(Error('Could not load the BPO editor.'));};document.head.append(s);}));}
async function access(){if(!user())return false;const id=user();const {data,error}=await client().rpc('bpo_enabled');return !error&&data===true&&id===user();}
function status(message){dialog?.querySelectorAll('[data-status],[data-subject-status]').forEach(n=>n.textContent=message);}
function modified(){dirty=true;status('Unsaved changes');}
function route(){const u=new URL(location.href);if(dialog){u.searchParams.set('bpo',record?.id||(dialog.classList.contains('pt-bpo-library-view')?'library':'new'));u.searchParams.set('bpo-step',String(step));}else{u.searchParams.delete('bpo');u.searchParams.delete('bpo-step');}history.replaceState(history.state,'',u);window.AppNavigationToolbar?.refresh?.();}
function release(){epoch++;dialog?.remove();dialog=null;record=null;values={};dirty=false;busy=false;document.body.classList.remove('pt-bpo-active');returnFocus?.focus?.();}
function close(){if(busy){status('Please wait for the current operation to finish.');return false;}if((dirty||pendingCompUploads())&&!confirm('Discard unsaved BPO changes and any files selected but not uploaded?'))return false;release();route();return true;}
function frame(){returnFocus=document.activeElement;dialog=document.createElement('section');dialog.id='ptBpoWorkspace';dialog.className='pt-bpo-workspace';dialog.setAttribute('aria-label','Comparable Sales / BPO workspace');dialog.innerHTML='<header><div><small>PRIVATE OWNER WORKSPACE</small><h1>Comparable Sales / BPOs</h1></div><button type="button" data-close>Income properties</button></header><p role="status" aria-live="polite" data-status></p><div data-body></div>';const shell=document.querySelector('main.shell')||document.querySelector('main')||document.body;shell.insertBefore(dialog,shell.querySelector(':scope > .footer'));document.body.classList.add('pt-bpo-active');dialog.querySelector('[data-close]').onclick=()=>{if(close()){bypass=true;document.getElementById('appNavExisting')?.click();bypass=false;}};dialog.scrollIntoView({block:'start'});}
