function clientFormEditable(){return !record?.id&&(step===1||(step===2&&!values._clientTemplateChosen));}
function clientFormControl(){const name=window.PropertyThesisBPOCore.clientOf(values)==='rrr'?'Residential Real Estate Review (RRR)':'General BPO';return clientFormEditable()?'<label class="pt-bpo-client-choice">Client form<select data-client-form><option value="general">General BPO</option><option value="rrr">Residential Real Estate Review (RRR)</option></select></label>':'<div class="pt-bpo-client-choice">Client form<strong data-client-form-name>'+name+'</strong></div>';}
