function refreshClientForm(){const host=dialog?.querySelector('.pt-bpo-client-choice');if(host){host.outerHTML=clientFormControl();bindClientForm();}}
function workflowLimit(libraryMode=false){return (libraryMode?clientFilter:values._clientTemplate)==='rrr'?5:8;}
function workflow(current=0,libraryMode=false){const names=['Subject Property','Sold & Active Comps','Neighborhood & Market','Adjustments','BPO Report','BPO Summary','Final PDF Package'],descriptions=['Enter an address or upload subject PDFs','Upload sold, active or pending listings','Enter market facts or upload sources','Review concessions and feature adjustments','Review your opinion & download PDF','Write and review the supporting narrative','Arrange sources & download the complete PDF'];{names.unshift('Upload Data Sources');descriptions.splice(0,3,'Review subject facts','Review sold and active/pending facts','Review neighborhood and market facts');descriptions.unshift('Upload PDFs and extract facts once');}return '<section class="pt-bpo-workflow-shell"><div class="pt-bpo-workflow-heading"><div><h2>Workflow Navigation</h2><p>Click a step to move through the BPO</p></div><strong>'+workflowLimit(libraryMode)+'-STEP COMPARABLE SALES WORKFLOW</strong></div><nav class="pt-bpo-workflow" data-step-count="'+workflowLimit(libraryMode)+'" aria-label="BPO workflow">'+names.slice(0,workflowLimit(libraryMode)).map((n,i)=>'<button '+(libraryMode?'data-library-step':'data-step')+'="'+(i+1)+'" '+(current===i+1?'aria-current="step"':'')+'><span class="pt-bpo-step-number">'+(i+1)+'</span><span class="pt-bpo-step-copy"><strong>'+n+'</strong><small>'+descriptions[i]+'</small></span><span class="pt-bpo-step-cue">Open →</span></button>').join('')+'</nav></section>';}
async function library(){const token=epoch;dialog.classList.add('pt-bpo-library-view');dialog.dataset.bpoMode='library';route();status('Loading your BPOs…');const {data:allData,error}=await client().from('bpo_reports').select('id,address,revision,updated_at,field_values').order('updated_at',{ascending:false});if(token!==epoch||!dialog)return;if(error){status('Unable to load BPOs: '+error.message);return;}const data=allData.filter(r=>window.PropertyThesisBPOCore.clientOf(r.field_values||{})===clientFilter);
 const C=window.PropertyThesisBPOCore;const count=(v,k)=>[1,2,3].filter(i=>v[k+'.'+i+'.address']).length;const cash=x=>C.number(x)!==null?'$'+C.money(C.number(x)):'Not entered';
 dialog.querySelector('[data-body]').innerHTML=workflow(0,true)+'<details class="pt-bpo-guide"><summary>How to create a BPO and add comparable evidence</summary><p>Create your subject manually or from a PDF. Add sold and active/pending listings, then neighborhood and market information. '+(clientFilter==='rrr'?'Review adjustments, then export to the RRR portal to finish the client form.':'Review the populated form and enter your final opinion before downloading the editable PDF.')+'</p></details><div class="pt-bpo-library-heading"><h2>Comparable Sales Properties</h2><label>Client form <select data-client-filter><option value="general">General BPO — Realtors / sellers / buyers</option><option value="rrr">Residential Real Estate Review (RRR)</option></select></label><span>'+data.length+' saved '+(data.length===1?'property':'properties')+'</span><button class="primary" data-new>New BPO</button><button data-refresh>Refresh</button></div><p data-property-prompt>Select a saved property below, or create a new subject using Step 1.</p><div class="pt-bpo-library">'+(data.length?data.map(r=>{const v=r.field_values||{};return '<article><h3>'+esc(r.address)+'</h3><p class="pt-bpo-card-address">'+esc(r.address)+'</p><div class="pt-bpo-card-metrics"><div><small>Subject Price</small><strong>'+esc(cash(v['sold.0.price']))+'</strong></div><div><small>Sold Comps</small><strong>'+count(v,'sold')+'</strong></div><div><small>Active / Pending</small><strong>'+count(v,'active')+'</strong></div><div><small>BPO Value (As Is)</small><strong>'+esc(cash(v.field_0477))+'</strong></div></div><p class="pt-bpo-card-updated"><b>Updated:</b> '+esc(new Date(r.updated_at).toLocaleDateString())+'</p><div class="pt-bpo-card-actions"><button data-open="'+esc(r.id)+'">Open Property</button><button data-open-report="'+esc(r.id)+'" data-target-step="2">Sold & Active Comps</button><button data-open-report="'+esc(r.id)+'" data-target-step="3">Neighborhood & Market</button><button data-open-report="'+esc(r.id)+'" data-target-step="4">Adjustments</button>'+(clientFilter==='rrr'?'':'<button data-open-report="'+esc(r.id)+'" data-target-step="5">BPO Report</button><button data-open-report="'+esc(r.id)+'" data-target-step="6">BPO Summary</button><button data-open-report="'+esc(r.id)+'" data-target-step="7">Final PDF Package</button>')+'<button type="button" class="danger" data-delete-bpo="'+esc(r.id)+'">Delete Property</button></div></article>';}).join(''):'<p>No comparable sales properties saved yet. Start with Step 1 above.</p>')+'</div>';
 dialog.querySelector('[data-client-filter]').value=clientFilter;dialog.querySelector('[data-client-filter]').onchange=e=>{clientFilter=e.target.value;library();};const start=()=>{record=null;values={_clientTemplate:clientFilter};dirty=false;step=1;editor();};dialog.querySelector('[data-new]').onclick=start;dialog.querySelector('[data-refresh]').onclick=()=>library();let selectedStep=1;
 dialog.querySelectorAll('[data-library-step]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.libraryStep);if(n===1)return start();selectedStep=n;dialog.querySelectorAll('[data-library-step]').forEach(x=>{if(x===b)x.setAttribute('aria-current','step');else x.removeAttribute('aria-current');});dialog.querySelector('[data-property-prompt]').textContent='Choose the saved property below to open Step '+n+'.';dialog.querySelector('.pt-bpo-library-heading').scrollIntoView({block:'start'});});
 dialog.querySelectorAll('[data-delete-bpo]').forEach(b=>b.onclick=()=>run(t=>deleteBPO(b.dataset.deleteBpo,t)));
 dialog.querySelectorAll('[data-open],[data-open-report]').forEach(b=>b.onclick=async()=>{const {data:r,error:e}=await client().from('bpo_reports').select('*').eq('id',b.dataset.open||b.dataset.openReport).single();if(token!==epoch||!dialog)return;if(e)return status(e.message);record=r;values=window.PropertyThesisBPOCore.normalize(r.field_values||{});dirty=false;step=b.dataset.targetStep?Number(b.dataset.targetStep)+1:selectedStep;editor();if(values._clientTemplate!=='rrr')await run(async t=>{if(await refreshProximity(t)&&dirty)await save(t,true);});dialog.querySelector('.pt-bpo-workflow-shell').scrollIntoView({block:'start'});});route();status('Only specifically enabled accounts can access this workspace.');}
async function deleteBPO(reportId,token=epoch){
 if(!(await access()))throw Error('BPO access is unavailable. Please sign in with an enabled account.');
 const id=user(),db=client();const {data:r,error}=await db.from('bpo_reports').select('*').eq('id',reportId).eq('user_id',id).maybeSingle();
 if(token!==epoch||id!==user())return;if(error||!r)throw Error('This property could not be loaded. Refresh your saved properties and try again.');
 if(!confirm('Permanently delete '+r.address+'? This removes this saved BPO, its summary, and its uploaded source PDFs. PDFs already downloaded to your computer are not affected.'))return;
 const paths=[...new Set((r.field_values?._attachments||[]).map(d=>d.path))];
 if(paths.some(path=>typeof path!=='string'||!path.startsWith(id+'/'+reportId+'/')||path.includes('..')))throw Error('A source file reference needs review; the property was not deleted.');
 if(paths.length){const {error:e}=await db.storage.from('bpo-documents').remove(paths);if(token!==epoch||id!==user())return;if(e)throw Error('Uploaded files could not be removed. The saved property was kept; please retry. '+e.message);}
 const {data:removed,error:deleteError}=await db.from('bpo_reports').delete().eq('id',reportId).eq('user_id',id).eq('revision',r.revision).select('id').maybeSingle();
 if(token!==epoch||id!==user())return;
 if(deleteError||!removed)throw Error((paths.length?'Uploaded files were removed, but the BPO record could not be deleted. ':'The BPO could not be deleted. ')+'Refresh and retry; it may have changed in another window.');
 record=null;values={};dirty=false;await library();status('Deleted '+r.address+'.');
}
function collect(){if(!dialog)return;if(dialog.querySelector('[data-summary-note]')){values._summaryNotes=window.PropertyThesisBPOCore.summaryNotes(values);dialog.querySelectorAll('[data-summary-note]').forEach(el=>values._summaryNotes[el.dataset.summaryNote]=el.value);}dialog.querySelectorAll('[data-comp-address]').forEach(el=>{const C=window.PropertyThesisBPOCore;if(el.value.trim()!==C.comparableAddress(values,el.dataset.compAddress))values=C.editComparableAddress(values,el.dataset.compAddress,el.value.trim());});dialog.querySelectorAll('[data-bpo-field]').forEach(el=>{values[el.dataset.bpoField]=el.type==='checkbox'?el.checked:el.value;});dialog.querySelectorAll('[data-subject-field]').forEach(el=>{for(const k of ['sold','active'])if(el.dataset.subjectField!=='price'||k==='active')values[k+'.0.'+el.dataset.subjectField]=el.value;});const address=dialog.querySelector('[data-address]');if(address&&address.value.trim()){values=window.PropertyThesisBPOCore.subjectAddress(values,address.value.trim());if(window.PropertyThesisBPOCore.validAddress(address.value))delete values._subjectPending;}dialog.querySelectorAll('[data-summary-body]').forEach(el=>{if(values._summary)values._summary.sections[Number(el.dataset.summaryBody)].body=el.value;});const previousGenerated=values._adjustments?.generated||{};values=window.PropertyThesisBPOCore.applyAdjustments(values).values;for(const key of new Set([...Object.keys(previousGenerated),...Object.keys(values._adjustments?.generated||{})])){const generated=values._adjustments?.generated?.[key];if((generated&&window.PropertyThesisBPOCore.number(values[key])===window.PropertyThesisBPOCore.number(generated.value))||(!generated&&values[key]==='')){const el=dialog.querySelector('[data-bpo-field="'+key+'"]');if(el)el.value=values[key];}}for(const [name,key,p] of [['primary_sold_comp','primary','sold'],['primary_active_comp','primaryActive','active']]){if(dialog.querySelector('[data-bpo-field="'+name+'"]')){values._summaryNotes||={};values._summaryNotes[key]=values[name]?p+'.'+values[name].split(' ').pop():'';}}}
function refreshPrimaryOptions(){const C=window.PropertyThesisBPOCore;for(const [name,p] of [['primary_sold_comp','sold'],['primary_active_comp','active']]){const el=dialog.querySelector('[data-bpo-field="'+name+'"]');if(el){const selected=values[name]||'';el.innerHTML=C.primaryOptions(values,p).map(o=>'<option value="'+o.value+'">'+esc(o.label)+'</option>').join('');el.value=selected;}}}
function showValues(){refreshPrimaryOptions();dialog.querySelectorAll('[data-comp-address]').forEach(el=>el.value=window.PropertyThesisBPOCore.comparableAddress(values,el.dataset.compAddress));dialog.querySelectorAll('[data-bpo-field]').forEach(el=>{const v=window.PropertyThesisBPOCore.formatValue(el.dataset.bpoField,values[el.dataset.bpoField]);if(el.type==='checkbox')el.checked=v===true;else if(el.value!==String(v??''))el.value=String(v??'');});dialog.querySelectorAll('[data-subject-field]').forEach(el=>el.value=values[(el.dataset.subjectField==='price'?'active':'sold')+'.0.'+el.dataset.subjectField]??'');}
