 if(f.kind==='select'){const p=f.name==='primary_sold_comp'?'sold':'active';return '<select '+a+'>'+C.primaryOptions(values,p).map(o=>'<option value="'+esc(o.value)+'">'+esc(o.label)+'</option>').join('')+'</select>';}
 return f.kind==='textarea'?'<textarea '+a+'></textarea>':'<input '+a+' type="'+(f.kind==='check'?'checkbox':'text')+'">';
