 if(window.PropertyThesisBPOCore.validAddress(values.field_0008)){delete values._subjectPending;values=window.PropertyThesisBPOCore.subjectAddress(values,values.field_0008);const address=dialog.querySelector('[data-address]');if(address)address.value=values.field_0008;}
 renderAI();
