 host.innerHTML=notes.map(n=>'<p>'+esc(n)+'</p>').join('')+'<ul>'+Object.entries(sources).map(([name,s])=>'<li><strong>'+esc(window.PropertyThesisBPOCore.byName.get(name)?.label||name)+'</strong>: '+esc(s.filename)+'  -  page '+esc(s.page)+(s.removed?' (source file deleted)':'')+'  -  '+esc(s.evidence)+'</li>').join('')+'</ul>';
