function categoryOf(d){if(d.sourceKind==='imapp')return 'imapp';if(d.sourceKind==='tax'||d.packageRole==='tax')return 'tax';if(['subject','sold','active','market'].includes(d.category))return d.category;const n=d.name.toLowerCase();return /sold.*comp/.test(n)?'sold':/active.*comp/.test(n)?'active':/neighborhood|market|imapp/.test(n)?'market':/subject|active mls/.test(n)?'subject':'other';}
